function makeDistCurve() {
  const N = 1024;
  const curve = new Float32Array(N);
  for (let i = 0; i < N; i++) {
    const x = (i / (N - 1)) * 2 - 1;
    const k = 3.5;
    curve[i] = Math.tanh(x * k);
  }
  return curve;
}
